const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '0.25' },
      { kind: 'text', payload: '0.5' },
      { kind: 'text', payload: '0.75' },
      { kind: 'text', payload: '1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = Math.round(W * 0.10);
    var x1 = Math.round(W * 0.90);
    var y = Math.round(H * 0.50);
    var labels = ['0', '0.25', '0.5', '0.75', '1'];
    var stroke = '#26354a';
    var paths = [];
    var children = [];

    paths.push({ id: 'axis', commands: visualSdk.polyline([[x0, y], [x1, y]]) });
    children.push({ type: 'path', pathId: 'axis', stroke: stroke, strokeWidth: 2, fill: 'none' });

    paths.push({ id: 'axisHead', commands: visualSdk.polyline([[x1 - 10, y - 5], [x1, y], [x1 - 10, y + 5]]) });
    children.push({ type: 'path', pathId: 'axisHead', stroke: stroke, strokeWidth: 2, fill: 'none' });

    for (var i = 0; i < 5; i++) {
      var x = x0 + (x1 - x0) * i / 4;
      var tickId = 'tick' + i;
      paths.push({ id: tickId, commands: visualSdk.polyline([[x, y - 7], [x, y + 7]]) });
      children.push({ type: 'path', pathId: tickId, stroke: stroke, strokeWidth: 2, fill: 'none' });
      children.push({
        type: 'label',
        text: labels[i],
        x: x,
        y: y + 28,
        fontSize: 14,
        align: 'center',
        baseline: 'middle',
        fill: stroke
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'axis-0-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
